/* Compartilhado pelo prerender estático e pelo navegador: uma única origem de conteúdo. */
(() => {
  'use strict';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function safeUrl(value) {
    if (typeof value !== 'string' || !value.trim() || /[\u0000-\u0020\\]/.test(value)) return '';
    if (/^https?:\/\//i.test(value)) { try { const u=new URL(value); return u.username||u.password ? '' : u.href; } catch { return ''; } }
    return /^(?:\.\/)?assets\/[a-zA-Z0-9_./%-]+$/.test(value) && !value.includes('..') ? value : '';
  }
  const emailValid = value => typeof value==='string' && /^[^\s@<>?&#]+@[^\s@<>?&#]+\.[^\s@<>?&#]+$/.test(value);
  const link = (url,label,download=false) => safeUrl(url) ? `<a class="text-link" aria-label="${esc(label)}${!download&&/^https?:/.test(url)?', abre em nova aba':''}" href="${esc(safeUrl(url))}" ${download?'download':/^https?:/.test(url)?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)} <span aria-hidden="true">${download?'↓':'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M5 19 19 5M5 5h14v14"/></svg>'}</span></a>` : '';
  function preview(p) {
    if (safeUrl(p.image)) return `<img class="preview project-image" src="${esc(p.image)}" alt="${esc(p.imageAlt||'Interface de '+p.name)}" loading="lazy" decoding="async" width="1200" height="750">`;
    const toolbar='<div class="preview-toolbar"><i></i><i></i><i></i><span>ESTUDO DE INTERFACE · DADOS ILUSTRATIVOS</span></div>';
    if(p.type==='sonora')return `<div class="preview sonora" aria-hidden="true">${toolbar}<div class="sonora-body"><div class="sonora-title"><small>SONORA / LISTENING SPACE</small>Seu ritmo.<br>Novas descobertas.<div class="waveform">${Array.from({length:24},(_,i)=>`<i style="height:${20+((i*37+13)%78)}%"></i>`).join('')}</div></div><div class="track-list"><div>01 <span>Entre tempos</span> 3:42</div><div>02 <span>Horizonte azul</span> 4:18</div><div>03 <span>Depois da chuva</span> 2:56</div><div>04 <span>Frequência</span> 3:27</div></div></div><div class="preview-footer">ON REPEAT / ESTA SEMANA</div></div>`;
    return `<div class="preview atlas" aria-hidden="true">${toolbar}<div class="atlas-body"><div class="atlas-header"><strong>atlas.</strong><span>SUA SEMANA / VISÃO GERAL</span></div><div class="atlas-metrics"><span>TEMPO DE FOCO<b>24h 32m</b></span><span>ATIVIDADES<b>18 / 24</b></span><span>CONSISTÊNCIA<b>86%</b></span></div><div class="chart">${[35,55,42,72,63,85,47,62,80,95,65,76].map(n=>`<i style="height:${n}%"></i>`).join('')}</div></div></div>`;
  }
  function projectDetail(p) { return `<p>${esc(p.description)}</p><h3>Contexto</h3><p>${esc(p.problem)}</p><h3>Direção da solução</h3><p>${esc(p.solution)}</p>${p.result?`<h3>Resultado verificável</h3><p>${esc(p.result)}</p>`:''}<h3>${p.concept?'Status do estudo':'Aprendizados'}</h3><p>${esc(p.learning)}</p><div class="dialog-links">${link(p.demo,'Abrir demo')}${link(p.repository,'Ver repositório')}${link(p.caseStudy,'Ler case study')}</div>`; }
  function projects(data) { return data.projects.map((p,i)=>`<article class="project reveal" id="project-${esc(p.id)}"><div class="project-chapter"><span class="mono">ESTUDO ${String(i+1).padStart(2,'0')}</span><span class="mono">${esc(p.category)} / ${esc(p.year)}</span></div><div class="project-header"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></div><div class="project-media">${preview(p)}<span class="media-label">${p.concept?'CONCEITO · NÃO PUBLICADO':'PRÉVIA DO PROJETO'}</span><button class="media-open js-only" data-project="${esc(p.id)}" aria-label="Ver detalhes de ${esc(p.name)}">Explorar ${esc(p.name)} ↗</button></div><div class="project-info"><div><span class="mono">${esc(p.stack)}</span>${p.role?`<p class="project-role">Papel: ${esc(p.role)}</p>`:''}</div><p>${p.result?esc(p.result):p.concept?'Estudo visual. Sem integração ou resultados de produção.':'Detalhes e decisões de implementação abaixo.'}</p></div><details class="project-details"><summary>Contexto e decisões de ${esc(p.name)}</summary>${projectDetail(p)}</details></article>`).join(''); }
  function socials(data) {
    const entries=[['GitHub',data.github],['LinkedIn',data.linkedin],['Email',emailValid(data.email)?'mailto:'+data.email:''],['Currículo',data.resume],['Instagram',data.instagram]].filter(([,url])=>url&&(url.startsWith('mailto:')||safeUrl(url)));
    if(!entries.length) return '';
    return entries.map(([name,url],i)=>`<div class="social-line"><a class="social-row" aria-label="${esc(name)} de ${esc(data.name)}${name!=='Email'&&name!=='Currículo'?', abre em nova aba':''}" href="${esc(url)}" ${name==='Currículo'?'download':name!=='Email'?'target="_blank" rel="noopener noreferrer"':''}><span class="mono">${String(i+1).padStart(2,'0')}</span><span class="social-name">${name}</span><span class="social-detail">${esc(name==='Email'?data.email:name==='Currículo'?'Baixar PDF':url.replace(/^https?:\/\//,'').replace(/\/$/,''))}</span><span class="social-arrow" aria-hidden="true"><svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M5 19 19 5M5 5h14v14"/></svg></span>${name!=='Email'&&name!=='Currículo'?'<span class="sr-only">Abre em nova aba</span>':''}</a>${name==='Email'?'<button class="copy-email text-link js-only">Copiar email</button>':''}</div>`).join('');
  }
  const categoryNames={'cloud-devops':'Cloud & DevOps','ai-data':'IA & dados',development:'Desenvolvimento',security:'Segurança',other:'Outros'};
  const validCertificates = list => list.filter(c=>c.id&&c.title&&c.issuer&&/^\d{4}-\d{2}-\d{2}$/.test(c.issueDate)&&!Number.isNaN(Date.parse(c.issueDate))&&categoryNames[c.category]).sort((a,b)=>b.issueDate.localeCompare(a.issueDate));
  const dateLabel = date => new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));
  function certificateDetail(c){return `<p id="certificate-description">${esc(c.description||'Credencial emitida por '+c.issuer+'.')}</p>${safeUrl(c.image)?`<img class="certificate-image" src="${esc(c.image)}" alt="Certificado de ${esc(c.title)}, emitido por ${esc(c.issuer)}" width="1200" height="850" loading="lazy" decoding="async">`:''}<p>${esc(c.issuer)} · ${esc(dateLabel(c.issueDate))}</p><p>${esc((c.skills||[]).join(' · '))}</p><div class="dialog-links">${link(c.credentialUrl,'Verificar credencial')}${link(c.downloadUrl||c.image,'Baixar certificado',true)}</div>`;}
  function certificates(list){const sorted=validCertificates(list);if(!sorted.length)return '<div class="certificate-empty"><span class="empty-index" aria-hidden="true">↗</span><div><h3>Conhecimento que vira prática.</h3><p>Estudo, experimento e aplico. O aprendizado se conecta ao que construo.</p></div></div>';
    const featured=sorted.filter(c=>c.featured).slice(0,4);const rest=sorted.filter(c=>!featured.includes(c));const groups=new Set(sorted.map(c=>c.category));
    const card=(c,large)=>`<article class="certificate ${large?'featured':''}" data-category="${esc(c.category)}">${large&&safeUrl(c.image)?`<img class="certificate-thumb" src="${esc(c.image)}" alt="Certificado de ${esc(c.title)}" loading="lazy" decoding="async" width="1200" height="850">`:''}<div><span class="mono">${esc(categoryNames[c.category])} / <time datetime="${esc(c.issueDate)}">${esc(dateLabel(c.issueDate))}</time></span><h3>${esc(c.title)}</h3><p>${esc(c.issuer)}</p><p class="certificate-skills">${esc((c.skills||[]).join(' · '))}</p><div class="certificate-actions"><button class="text-link js-only" data-certificate="${esc(c.id)}">Ver certificado<span class="sr-only">: ${esc(c.title)}</span></button>${link(c.credentialUrl,'Verificar credencial')}</div><details class="no-js-only"><summary>Ver certificado: ${esc(c.title)}</summary>${certificateDetail(c).replace(' id="certificate-description"','')}</details></div></article>`;
    return `${sorted.length>=6&&groups.size>1?`<div class="certificate-filters js-only" role="group" aria-label="Filtrar certificados"><button data-filter="all" aria-pressed="true">Todos</button>${[...groups].map(g=>`<button data-filter="${g}" aria-pressed="false">${categoryNames[g]}</button>`).join('')}</div>`:''}<div class="certificate-featured">${featured.map(c=>card(c,true)).join('')}</div><div class="certificate-list">${rest.map(c=>card(c,false)).join('')}</div><p id="certificate-filter-status" class="mono" role="status"></p>`;}
  const skills=data=>data.skills.map((s,i)=>`<div class="skill-row reveal"><span class="mono">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s.name)}</h3><small>${esc(s.caption)}</small></div><p>${esc(s.items)}</p></div>`).join('');
  const now=data=>`<ul class="now-list">${data.currentFocus.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`;
  const soft=data=>data.softSkills.map(s=>`<div><h3>${esc(s.name)}</h3><p>${esc(s.context)}</p></div>`).join('');
  const contact=data=>emailValid(data.email)?`<a class="contact-button" href="mailto:${esc(data.email)}">${esc(data.email)} <span aria-hidden="true">↗</span></a>`:`<div class="contact-networks">${[['LinkedIn',data.linkedin],['GitHub',data.github],['Instagram',data.instagram]].map(([name,url])=>link(url,'Conversar no '+name)).join('')}</div>`;
  window.PortfolioRender={esc,safeUrl,emailValid,link,projects,projectDetail,socials,certificates,certificateDetail,validCertificates,skills,now,soft,contact};
})();
